                    ) : null}
                </Flex>

                <div className="viz-widget__chart" style={{height: chartHeight}}>
                    <ChartArea view={view} palette={palette} />
                </div>

                {showSummary ? <SummaryTable view={view} palette={palette} /> : null}
            </Flex>
        </Card>
    );
}
